1	import { parseStock } from './input/csv.js';
2	import { normalizeStock } from './domain/stock.js';
3	import { wireStock } from './output/wire.js';
4	export function importStock(text) { return wireStock(normalizeStock(parseStock(text))); }

1	import { canonicalSku } from './sku.js';
2	export function normalizeStock(row) {
3	  if (![row.available, row.reserved].every(Number.isFinite)) throw new Error('invalid count');
4	  return { sku: canonicalSku(row.sku), count: Math.max(0, row.available - row.reserved) };
5	}

1	export function parseStock(text) {
2	  const [sku, available, reserved] = text.trim().split(',');
3	  return { sku, available: Number(available), reserved: Number(reserved) };
4	}

item.command:
/bin/zsh -lc "node --input-type=module <<'NODE'
import { strict as assert } from 'node:assert';
import { readFileSync, writeFileSync } from 'node:fs';
import { importStock } from './src/entry.js';

const output = importStock(' ab-2 ,5,8');
assert.deepEqual(output, { product_code: 'AB-2', units: 0, schema: 2 });
let invalidNumeric;
try {
  importStock('x,no,1');
  assert.fail('Expected invalid numeric input to throw');
} catch (error) {
  assert.equal(error.message, 'invalid count');
  invalidNumeric = error.message;
}
assert.deepEqual(importStock('x,5,2'), { product_code: 'X', units: 3, schema: 2 });
assert.deepEqual(importStock('x,-2,-3'), { product_code: 'X', units: 1, schema: 2 });
assert.deepEqual(importStock('x,-2,1'), { product_code: 'X', units: 0, schema: 2 });
const answer = {
  files: ['src/entry.js', 'src/input/csv.js', 'src/domain/stock.js', 'src/domain/sku.js', 'src/output/wire.js'],
  output,
  invalid_numeric: invalidNumeric,
  reserved_applied_before_clamp: true
};
writeFileSync('answer.json', "'`${JSON.stringify(answer, null, 2)}'"\\n"'`);
assert.deepEqual(JSON.parse(readFileSync('"'answer.json', 'utf8')), answer);
console.log(JSON.stringify({status: 'passed', answer}));
NODE"

